    // Exact editor model for the portable lowerCamel authority schema.
    [JsonObject(MemberSerialization.OptIn)]
    public sealed class VfxDesignContract
    {
        [JsonProperty("contractVersion")] public string ContractVersion;
        [JsonProperty("effectId")] public string EffectId;
        [JsonProperty("contractRevision")] public int ContractRevision;
        [JsonProperty("contractHash")] public string ContractHash;
        [JsonProperty("lifecycle")] public VfxLifecycle Lifecycle;
        [JsonProperty("references")] public VfxReference[] References = Array.Empty<VfxReference>();
        [JsonProperty("spatialContract")] public VfxSpatialContract SpatialContract;
        [JsonProperty("captureProfile")] public VfxCaptureContract CaptureProfile;
        [JsonProperty("semanticStateMachine")] public VfxSemanticStateMachine SemanticStateMachine;
        [JsonProperty("layers")] public VfxLayer[] Layers = Array.Empty<VfxLayer>();
        [JsonProperty("allowedSubstitutions")] public VfxSubstitution[] AllowedSubstitutions = Array.Empty<VfxSubstitution>();
        [JsonProperty("forbiddenSubstitutions")] public VfxSubstitution[] ForbiddenSubstitutions = Array.Empty<VfxSubstitution>();
        [JsonProperty("cleanup")] public VfxCleanupContract Cleanup;
        [JsonProperty("budget")] public VfxBudgetContract Budget;
        [JsonProperty("requirements")] public VfxDesignRequirement[] Requirements = Array.Empty<VfxDesignRequirement>();
        [JsonProperty("extensions")] public JObject Extensions;
        [JsonIgnore] internal string AuthorityCanonicalHash;
        public string ComputeContractHash() { return VfxDesignContractJson.ComputeContractHash(this); }
        public static VfxDesignContract FromJson(string json) { return VfxDesignContractJson.FromJson(json); }
    }

